before:
Complete local C++ example; the app itself does not execute it:
```cpp
#include <fstream>
#include <iostream>
#include <string>
int main() {
    {
        std::ofstream out("practice.txt");
        if (!out) return 1;
        out << "first";
        out.close();
        if (!out) return 1;
    }
    {
        std::ofstream out("practice.txt");
        if (!out) return 1;
        out << "second";
        out.close();
        if (!out) return 1;
    }
    std::ifstream in("practice.txt");
    std::string text;
    if (!in || !std::getline(in, text)) return 1;
    std::cout << text << "\n";
}
```

